// dsl.js — the parser every fedwiki plugin with a command table needs.
//
// The convention is fedwiki-wide: in an item's text, an UPPERCASE first word is
// a command, lowercase is data, and a single trailing colon is optional. Each
// plugin writes its own table of commands; none of them should write this again.
//
// A table is an object of WORD → entry, and every entry declares its `kind`:
//
//   parameter    supplies an argument to a call          → crosses to HTTP
//   macro        shorthand expanding to other commands   → expands, then crosses
//   client-data  no server can supply it                 → never crosses
//   presentation changes only how it is drawn            → never crosses
//   alias        another spelling of a command           → resolves first
//
// Those are the kinds wiki-plugin-farm's vocabulary check accepts, so a table
// this module can read is a table the farm can mount. What the farm cannot do is
// read item TEXT — it has no DOM and no parser — which is why this lives in the
// browser, beside the table, rather than in the farm.
//
// Usage, in a plugin's own commands module:
//
//   import { dsl } from '@fortyfoxes/wiki-dsl'
//   export const COMMANDS = { … }
//   export const { parseKinds, hasCommand, argumentOf, problems } = dsl(COMMANDS)

/** Values an argument may take to mean "no". */
const FALSEY = ['no', 'false', 'off', '0', 'hide', 'none']

/** Announces itself as a command: uppercase, letters only, two or more. */
const COMMAND_LIKE = /^[A-Z][A-Z]+$/

/** Levenshtein distance. Only ever run over single short words. */
const distance = (a, b) => {
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j)
  for (let i = 1; i <= a.length; i++) {
    const row = [i]
    for (let j = 1; j <= b.length; j++) {
      row[j] = Math.min(prev[j] + 1, row[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1))
    }
    prev = row
  }
  return prev[b.length]
}

/**
 * The keyword a line begins with, normalised. UPPERCASE is canonical but input
 * case is forgiven, and one trailing colon is optional — never required.
 */
export const keywordOf = line =>
  String(line || '')
    .trim()
    .split(/\s+/)[0]
    .replace(/:$/, '')
    .toUpperCase()

/**
 * Bind the helpers to one plugin's table. `fallback` is what parseKinds answers
 * when the text names nothing — the plugin's own default.
 */
export const dsl = (COMMANDS, { fallback = [] } = {}) => {
  /** Follow an alias to the command it spells. */
  const resolve = name => {
    const entry = COMMANDS[name]
    return entry && entry.kind === 'alias' ? COMMANDS[entry.alias] : entry
  }

  /** The canonical name a command resolves to, for reporting. */
  const canonical = name => {
    const entry = COMMANDS[name]
    return entry && entry.kind === 'alias' ? entry.alias : name
  }

  /** Every value a parameter may take, in declaration order. The API's enum. */
  const valuesFor = parameter =>
    Object.values(COMMANDS)
      .filter(c => c.kind === 'parameter' && c.parameter === parameter && c.value)
      .map(c => c.value)

  /** One field of the table, keyed by value — labels(), headings('heading'), … */
  const fieldByValue = field => {
    const out = {}
    for (const c of Object.values(COMMANDS)) if (c.value && c[field]) out[c.value] = c[field]
    return out
  }

  /**
   * Item text to an ordered, de-duplicated list of values. Macros expand in
   * place, aliases resolve, unrecognised lines are ignored as data rather than
   * treated as an error.
   */
  const parseKinds = (text, { fallback: given = fallback } = {}) => {
    const kinds = []
    const take = name => {
      const entry = resolve(name)
      if (!entry) return
      if (entry.kind === 'macro') return entry.expands.forEach(take)
      if (!entry.value) return
      if (!kinds.includes(entry.value)) kinds.push(entry.value)
    }
    for (const line of String(text || '').split('\n')) {
      if (line.trim()) take(keywordOf(line))
    }
    return kinds.length ? kinds : [...given]
  }

  /** Whether a bare command appears on a line of its own. */
  const hasCommand = (text, name) =>
    String(text || '')
      .split('\n')
      .some(line => canonical(keywordOf(line)) === name)

  /**
   * The argument written after a command — `TITLE no` — as a boolean. Absent
   * means the command's declared default.
   */
  const argumentOf = (text, name) => {
    for (const raw of String(text || '').split('\n')) {
      if (canonical(keywordOf(raw)) !== name) continue
      const arg = (raw.trim().split(/\s+/)[1] || '').toLowerCase().replace(/:$/, '')
      return !FALSEY.includes(arg)
    }
    return COMMANDS[name]?.default
  }

  /** The command a mistyped word most likely meant, or null when nothing is close. */
  const suggest = word => {
    const w = String(word || '').trim().replace(/:$/, '').toUpperCase()
    if (!w) return null
    let best = null
    let bestDistance = Infinity
    for (const name of Object.keys(COMMANDS)) {
      const d = distance(w, name)
      if (d < bestDistance) {
        bestDistance = d
        best = name
      }
    }
    return bestDistance <= (w.length <= 4 ? 1 : 2) ? canonical(best) : null
  }

  /**
   * Lines that look like a command and are not one, in order — each with the
   * word as written and the command it probably meant (null when unguessable).
   *
   * A mistyped command is worse than an unknown one: CHIKDREN names nothing, so
   * the item falls back and draws something the author never asked for, with
   * nothing on it saying why. Parsing is unaffected — this only gives the plugin
   * something true to say. Uppercase announces "command" out loud; a lone word
   * one typo from a real command says it quietly; ordinary prose says neither
   * and stays data.
   */
  const problems = text => {
    const found = []
    for (const raw of String(text || '').split('\n')) {
      const line = raw.trim()
      if (!line || resolve(keywordOf(line))) continue
      const word = line.split(/\s+/)[0].replace(/:$/, '')
      const suggestion = suggest(word)
      const alone = line.split(/\s+/).length === 1
      if (!COMMAND_LIKE.test(word) && !(alone && suggestion)) continue
      found.push({ word, suggestion })
    }
    return found
  }

  return { resolve, canonical, valuesFor, fieldByValue, parseKinds, hasCommand, argumentOf, suggest, problems }
}
